(function(){const i=document.querySelector('[id^="pickup-availability-"]');i&&(i.addEventListener("click",e=>{const t=e.target.closest(".pickup-row-trigger");if(!t||!i.contains(t))return;const a=document.getElementById(t.getAttribute("aria-controls"));if(!a)return;const r=t.getAttribute("aria-expanded")!=="true";t.setAttribute("aria-expanded",String(r)),a.hidden=!r,t.classList.toggle("bg-card-high",r),t.classList.toggle("bg-card-light",!r);const n=t.querySelector(".pickup-chevron");n&&(n.style.transform=r?"rotate(180deg)":"")}),document.addEventListener("variant-changed",e=>{!e.detail||!e.detail.variantId||i.querySelectorAll(".pickup-variant-state").forEach(t=>{t.hidden=t.dataset.variantId!==String(e.detail.variantId)})}))})();
